    except Exception:
        bias_prev = 0.0
    u_prev_raw = state.get("u", None)
    if not math.isfinite(I_prev):
        I_prev = 0.0
    if not math.isfinite(bias_prev):
        bias_prev = 0.0
    I_prev = _clamp(I_prev, IMIN, IMAX)
    bias_prev = _clamp(bias_prev, BMIN, BMAX)
    if yf_prev is None:
